import {SERVICES,civicRoots,civicRoot,civicMembers,isCivicRoot,civicServiceOperating} from './civic-footprints.js?v=architecture-collection-48';
// Prima structure garbage weights / 100; fixed monthly load per operating building.
export const CIVIC_WASTE={police:2.7,fire:2.7,hospital:2.16,school:3.6,jail:5.76,college:5.04,library:1.2,museum:1.2};
export function civicWasteProduction(c,t){return CIVIC_WASTE[t.type]&&isCivicRoot(t)&&civicServiceOperating(c,t)?CIVIC_WASTE[t.type]:0;}
export function civicWasteSources(c){return civicRoots(c).map(t=>({type:t.type,name:SERVICES[t.type].name,x:t.x,y:t.y,rate:civicWasteProduction(c,t),waiting:civicMembers(c,t).reduce((sum,u)=>sum+(u?.waste||0),0)}));}
export function civicGarbageInspection(c,t){t=civicRoot(c,t);if(!SERVICES[t.type])return '';const waiting=civicMembers(c,t).reduce((sum,u)=>sum+(u?.waste||0),0);return `<p>Garbage: ${civicWasteProduction(c,t).toFixed(2)} units/month · ${waiting.toFixed(2)} waiting. The whole building is counted once. Connect its road network to disposal capacity or a garbage-export route. Existing waste still needs collection when service is suspended.</p>`;}
export function civicWasteReport(c){const sources=civicWasteSources(c);if(!sources.length)return '';const groups=new Map(),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});for(const s of sources){const g=groups.get(s.type)||{name:s.name,count:0,active:0,rate:0,waiting:0};g.count++;g.active+=s.rate>0?1:0;g.rate+=s.rate;g.waiting+=s.waiting;groups.set(s.type,g);}return `<details><summary>Civic buildings · garbage</summary><p>Public services add ${fmt(sources.reduce((sum,s)=>sum+s.rate,0))} units/month to city garbage. This is included in total production.</p><div class="table-scroll"><table aria-label="Civic building garbage"><thead><tr><th>Service</th><th>Buildings</th><th>Operating</th><th>Units/month</th><th>Waiting</th></tr></thead><tbody>${[...groups.values()].map(g=>`<tr><th scope="row">${g.name}</th><td>${g.count}</td><td>${g.active}</td><td>${fmt(g.rate)}</td><td>${fmt(g.waiting)}</td></tr>`).join('')}</tbody></table></div><p>Inspect a building for its own backlog. Collection uses roads beside its whole footprint. A strike, zero funding, loss of electricity or damage stops new production; old garbage remains until collected.</p></details>`;}
